# Generated by build.py from recipe.yml for recipe imap-log-in-to-mail-with-a-token-from-an-agent. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > lunch.eml <<'EOF'
From: bob@example.com
To: ann@example.com
Subject: Lunch

Noon at the usual place.
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
dotnet run token-mail.cs
